PRAGMA foreign_keys = ON;
CREATE TABLE cases (id TEXT PRIMARY KEY, bank_id TEXT NOT NULL, organization_id TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, currency TEXT NOT NULL, amount_minor INTEGER NOT NULL CHECK(amount_minor>0), status TEXT NOT NULL CHECK(status IN ('Draft','Submitted','AwaitingClient')), revision INTEGER NOT NULL DEFAULT 1, created_by TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(bank_id,organization_id) REFERENCES organizations(bank_id,id));
CREATE INDEX cases_scope ON cases(bank_id,organization_id,updated_at);
CREATE TABLE documents (id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES cases(id), kind TEXT NOT NULL CHECK(kind IN ('contract','invoice')), original_name TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE document_versions (id TEXT PRIMARY KEY, document_id TEXT NOT NULL REFERENCES documents(id), case_id TEXT NOT NULL REFERENCES cases(id), version INTEGER NOT NULL, object_key TEXT NOT NULL UNIQUE, sha256 TEXT NOT NULL, size_bytes INTEGER NOT NULL CHECK(size_bytes<=10485760), media_type TEXT NOT NULL, uploaded_by TEXT NOT NULL, uploaded_at TEXT NOT NULL, UNIQUE(document_id,version));
CREATE TABLE case_audit (id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES cases(id), actor_id TEXT NOT NULL, action TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(case_id,action,detail));
